import{_ as a,o as i,c as l,a0 as t}from"./chunks/framework.Cp0xpwNH.js";const u=JSON.parse('{"title":"Flashcard Application Plan","description":"","frontmatter":{},"headers":[],"relativePath":"plans/FLASHCARD_APP_PLAN.md","filePath":"plans/FLASHCARD_APP_PLAN.md"}'),n={name:"plans/FLASHCARD_APP_PLAN.md"};function s(r,e,o,d,c,p){return i(),l("div",null,[...e[0]||(e[0]=[t(`<h1 id="flashcard-application-plan" tabindex="-1">Flashcard Application Plan <a class="header-anchor" href="#flashcard-application-plan" aria-label="Permalink to &quot;Flashcard Application Plan&quot;">​</a></h1><p><strong>Status:</strong> Planned <strong>Owner:</strong> Dutch B1 Curriculum project <strong>Target:</strong> Local-first vocabulary practice on desktop and iPhone</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Build a flashcard application for practicing the vocabulary in this repository. The application must use the existing vocabulary CSV files as its source of truth, automatically incorporate new words as they are researched, and keep personal review progress separate from educational content.</p><p>The first release is local-first. It will run in the existing VitePress site, work as a responsive web application, and be installable on an iPhone through Safari&#39;s <strong>Add to Home Screen</strong> feature.</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>Practice vocabulary through active recall and spaced repetition.</li><li>Select verbs, nouns, adjectives, other words, or a mixture.</li><li>Practice specific grammatical forms, including verb tenses and noun articles.</li><li>Mark cards as <code>Again</code>, <code>Hard</code>, <code>Good</code>, or <code>Confident</code>.</li><li>Show weak and due cards more frequently without permanently hiding confident cards.</li><li>Automatically discover new vocabulary from the CSV files after a rebuild.</li><li>Work offline after the application has been loaded or installed.</li><li>Support desktop and iPhone screen sizes and touch interaction.</li><li>Allow review data to be exported and imported as a backup.</li></ul><h2 id="non-goals-for-the-first-release" tabindex="-1">Non-Goals For The First Release <a class="header-anchor" href="#non-goals-for-the-first-release" aria-label="Permalink to &quot;Non-Goals For The First Release&quot;">​</a></h2><p>The following are deliberately deferred:</p><ul><li>User accounts</li><li>Cloud synchronization between devices</li><li>AI-generated vocabulary or sentences</li><li>Automatic speech recognition</li><li>Audio generation</li><li>Social or colleague-facing features</li><li>Typed-answer grading</li><li>Push notifications</li></ul><p>These features may be added later without changing the core vocabulary and review-data separation.</p><h2 id="existing-repository-constraints" tabindex="-1">Existing Repository Constraints <a class="header-anchor" href="#existing-repository-constraints" aria-label="Permalink to &quot;Existing Repository Constraints&quot;">​</a></h2><p>The repository is currently a VitePress documentation site. It has no separate application framework. The implementation should therefore extend the existing VitePress/Vue setup rather than introduce a second frontend application.</p><p>Vocabulary is stored in four authoritative files:</p><ul><li><code>shared/vocabulary/nouns.csv</code></li><li><code>shared/vocabulary/verbs.csv</code></li><li><code>shared/vocabulary/adjectives.csv</code></li><li><code>shared/vocabulary/other.csv</code></li></ul><p>The schemas contain part-of-speech-specific fields such as noun articles and plurals, verb forms and auxiliaries, and adjective comparison forms. Some files may be empty apart from their header while curriculum research is still in progress. The application must handle that state correctly.</p><p>The VitePress site is published under the <code>/dutch/</code> base path. The flashcard route must work at:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://metekahyagil.github.io/dutch/flashcards/</span></span></code></pre></div><h2 id="architectural-separation" tabindex="-1">Architectural Separation <a class="header-anchor" href="#architectural-separation" aria-label="Permalink to &quot;Architectural Separation&quot;">​</a></h2><p>The application will use three distinct layers:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vocabulary CSV files</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>Build-time vocabulary catalog</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>Generated card definitions</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>Flashcard interface</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>IndexedDB review state</span></span></code></pre></div><h3 id="educational-source-data" tabindex="-1">Educational Source Data <a class="header-anchor" href="#educational-source-data" aria-label="Permalink to &quot;Educational Source Data&quot;">​</a></h3><p>The four CSV files remain the single source of truth for vocabulary. The flashcard application must not write review results, UI settings, or generated data back into those files.</p><h3 id="generated-catalog" tabindex="-1">Generated Catalog <a class="header-anchor" href="#generated-catalog" aria-label="Permalink to &quot;Generated Catalog&quot;">​</a></h3><p>A build-time script will parse the CSV files and generate a normalized catalog consumed by the application. This catalog may be emitted as JSON or imported through the Vite build pipeline, but it must always be derived from the CSV files.</p><p>Running the build after adding a vocabulary row must be sufficient for the new word to become available. Adding a word must not require editing application source code or a manually maintained card list.</p><h3 id="personal-review-state" tabindex="-1">Personal Review State <a class="header-anchor" href="#personal-review-state" aria-label="Permalink to &quot;Personal Review State&quot;">​</a></h3><p>Review history will be stored locally in IndexedDB. It must remain separate from the generated catalog so that vocabulary content can be corrected or expanded without overwriting personal progress.</p><h2 id="dynamic-vocabulary-requirements" tabindex="-1">Dynamic Vocabulary Requirements <a class="header-anchor" href="#dynamic-vocabulary-requirements" aria-label="Permalink to &quot;Dynamic Vocabulary Requirements&quot;">​</a></h2><p>The catalog builder must:</p><ul><li>Read all four vocabulary CSV files on every build.</li><li>Preserve the source file and row metadata for each vocabulary item.</li><li>Normalize part-of-speech-specific fields into a common item structure.</li><li>Ignore blank rows.</li><li>Handle empty files that contain only a header.</li><li>Treat <code>--</code> as unavailable data where the schema uses it as a placeholder.</li><li>Validate required headers and report malformed rows clearly.</li><li>Preserve commas and quoted values in example sentences and notes.</li><li>Expose lesson, CEFR level, frequency rank, topic, and source file metadata.</li></ul><p>The generated catalog must not assume that all future rows have the same completeness as current rows. Cards should be generated only for fields that contain usable values.</p><h2 id="stable-identifiers" tabindex="-1">Stable Identifiers <a class="header-anchor" href="#stable-identifiers" aria-label="Permalink to &quot;Stable Identifiers&quot;">​</a></h2><p>Every generated card must have a stable identifier. Review state will be keyed by this identifier. Identifiers should be based on the vocabulary type, lemma, and skill being tested rather than on the CSV row number.</p><p>Examples:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>noun:huis:meaning:nl-en</span></span>
<span class="line"><span>noun:huis:article</span></span>
<span class="line"><span>noun:huis:plural</span></span>
<span class="line"><span>verb:gaan:meaning:nl-en</span></span>
<span class="line"><span>verb:gaan:present:ik</span></span>
<span class="line"><span>verb:gaan:past:plural</span></span>
<span class="line"><span>verb:gaan:perfect</span></span>
<span class="line"><span>adjective:groot:comparative</span></span></code></pre></div><p>The identifier strategy must be documented and tested before review data is released for regular use. If a word is corrected in place, its existing identifiers should retain their review history. If a lemma is intentionally renamed, the migration behavior must be explicit rather than silently losing the old state.</p><h2 id="card-model" tabindex="-1">Card Model <a class="header-anchor" href="#card-model" aria-label="Permalink to &quot;Card Model&quot;">​</a></h2><p>The application should model a vocabulary item separately from the cards generated from it.</p><h3 id="vocabulary-item" tabindex="-1">Vocabulary Item <a class="header-anchor" href="#vocabulary-item" aria-label="Permalink to &quot;Vocabulary Item&quot;">​</a></h3><p>A normalized item should include:</p><ul><li>Stable item identifier</li><li>Dutch lemma</li><li>English meaning</li><li>Part of speech</li><li>Pronunciation</li><li>CEFR level</li><li>Lesson introduced</li><li>Frequency rank</li><li>Topic</li><li>Example sentence</li><li>Example translation</li><li>Notes</li><li>Part-of-speech-specific forms</li></ul><h3 id="generated-card" tabindex="-1">Generated Card <a class="header-anchor" href="#generated-card" aria-label="Permalink to &quot;Generated Card&quot;">​</a></h3><p>Each card should include:</p><ul><li>Stable card identifier</li><li>Vocabulary item identifier</li><li>Card type</li><li>Prompt direction</li><li>Prompt data</li><li>Answer data</li><li>Relevant metadata for filtering</li></ul><p>The card definition is generated and can change when source data changes. The review state is local and must not be embedded in the card definition.</p><h2 id="initial-card-types" tabindex="-1">Initial Card Types <a class="header-anchor" href="#initial-card-types" aria-label="Permalink to &quot;Initial Card Types&quot;">​</a></h2><h3 id="nouns" tabindex="-1">Nouns <a class="header-anchor" href="#nouns" aria-label="Permalink to &quot;Nouns&quot;">​</a></h3><p>Generate cards for available fields:</p><ul><li>Dutch to English meaning</li><li>English to Dutch meaning</li><li>Article: <code>de</code> or <code>het</code></li><li>Plural</li><li>Diminutive</li></ul><p>Noun cards should display the article with the noun where that supports the learning objective. The article must not be treated as optional vocabulary metadata.</p><h3 id="verbs" tabindex="-1">Verbs <a class="header-anchor" href="#verbs" aria-label="Permalink to &quot;Verbs&quot;">​</a></h3><p>Generate cards for available fields:</p><ul><li>Dutch to English meaning</li><li>English to Dutch meaning</li><li>Present tense for <code>ik</code></li><li>Present tense for <code>jij/u/hij/zij/het</code></li><li>Present tense for <code>wij/jullie/zij</code></li><li>Simple past singular</li><li>Simple past plural</li><li>Auxiliary verb</li><li>Past participle and perfect-tense construction</li></ul><p>The UI should allow verb cards to be filtered by tense and subject grouping. Exceptions recorded in the source <code>Notes</code> field must be shown on the answer side.</p><h3 id="adjectives" tabindex="-1">Adjectives <a class="header-anchor" href="#adjectives" aria-label="Permalink to &quot;Adjectives&quot;">​</a></h3><p>Generate cards for available fields:</p><ul><li>Dutch to English meaning</li><li>English to Dutch meaning</li><li>Comparative</li><li>Superlative</li><li>Inflected form</li></ul><h3 id="other-words" tabindex="-1">Other Words <a class="header-anchor" href="#other-words" aria-label="Permalink to &quot;Other Words&quot;">​</a></h3><p>Generate cards for available fields:</p><ul><li>Dutch to English meaning</li><li>English to Dutch meaning</li><li>Part of speech</li><li>Example usage</li></ul><h2 id="study-configuration" tabindex="-1">Study Configuration <a class="header-anchor" href="#study-configuration" aria-label="Permalink to &quot;Study Configuration&quot;">​</a></h2><p>Before starting a session, the learner should be able to choose:</p><ul><li>Part of speech: verbs, nouns, adjectives, other, or mixed</li><li>CEFR level</li><li>Lesson or lesson range</li><li>Topic</li><li>Noun article: <code>de</code>, <code>het</code>, or both</li><li>Verb tense or form</li><li>Verb subject group</li><li>Card type</li><li>Direction: Dutch to English, English to Dutch, or mixed</li><li>Number of cards</li><li>Queue mode: due, new, weak, confident review, or mixed</li></ul><p>Filters should combine predictably. A mixed session should balance available card types so that one verb with many forms does not dominate a session of otherwise varied vocabulary.</p><p>When a filter produces no cards, the interface should explain why and offer a way to broaden the selection.</p><h2 id="review-experience" tabindex="-1">Review Experience <a class="header-anchor" href="#review-experience" aria-label="Permalink to &quot;Review Experience&quot;">​</a></h2><p>The first release will use flip-and-self-rate interaction rather than typed answers.</p><h3 id="card-front" tabindex="-1">Card Front <a class="header-anchor" href="#card-front" aria-label="Permalink to &quot;Card Front&quot;">​</a></h3><p>The front should show the prompt, prompt direction, and enough context to identify the task without revealing the answer.</p><p>Examples:</p><ul><li><code>___ huis</code> with the task &quot;Choose the article&quot;</li><li><code>to go</code> with the task &quot;Give the Dutch verb&quot;</li><li><code>gaan</code> with the task &quot;Past tense, plural&quot;</li><li><code>groot</code> with the task &quot;Give the comparative&quot;</li></ul><h3 id="card-back" tabindex="-1">Card Back <a class="header-anchor" href="#card-back" aria-label="Permalink to &quot;Card Back&quot;">​</a></h3><p>The back should show:</p><ul><li>Correct answer</li><li>Dutch lemma and English meaning</li><li>Pronunciation where available</li><li>Example sentence and translation</li><li>Relevant grammatical forms</li><li>Source lesson and topic</li><li>Notes and exceptions</li></ul><h3 id="ratings" tabindex="-1">Ratings <a class="header-anchor" href="#ratings" aria-label="Permalink to &quot;Ratings&quot;">​</a></h3><p>The learner should choose one of four ratings:</p><ul><li><code>Again</code> -- I did not know it.</li><li><code>Hard</code> -- I knew it slowly or with uncertainty.</li><li><code>Good</code> -- I knew it correctly.</li><li><code>Confident</code> -- I could produce it immediately.</li></ul><p>Ratings must be available as large touch controls on iPhone and as keyboard-accessible controls on desktop.</p><h2 id="scheduling-model" tabindex="-1">Scheduling Model <a class="header-anchor" href="#scheduling-model" aria-label="Permalink to &quot;Scheduling Model&quot;">​</a></h2><p>Each card has its own schedule. Knowing the meaning of <code>huis</code> does not automatically mean knowing its article, and knowing a verb&#39;s meaning does not imply knowing every tense.</p><p>The schedule should track at least:</p><ul><li>Card identifier</li><li>Due timestamp</li><li>Interval</li><li>Difficulty</li><li>Repetition count</li><li>Lapse count</li><li>Last rating</li><li>Last reviewed timestamp</li><li>Suspended status</li><li>Scheduler version</li></ul><p>The default queue order should be:</p><ol><li>Due cards</li><li>Failed or weak cards</li><li>New cards</li><li>Optional confident-card review</li></ol><p><code>Confident</code> should increase the interval substantially but must not permanently hide a card. Mature cards must return for occasional maintenance review.</p><p>The implementation should use a proven spaced-repetition algorithm, preferably FSRS, behind a small application adapter. The UI must not depend directly on the scheduler library so the algorithm can be changed or upgraded later.</p><h2 id="local-storage-and-backup" tabindex="-1">Local Storage And Backup <a class="header-anchor" href="#local-storage-and-backup" aria-label="Permalink to &quot;Local Storage And Backup&quot;">​</a></h2><p>IndexedDB will store:</p><ul><li>Review state</li><li>User study preferences</li><li>Session history or summary data</li><li>Suspended cards</li><li>Storage schema version</li></ul><p>The app must provide:</p><ul><li>Export of review data and settings as JSON</li><li>Import of a previously exported JSON backup</li><li>Validation before importing</li><li>Clear local progress with confirmation</li><li>A visible indication of the last backup or export</li></ul><p>Export and import must be versioned so future schema changes can migrate old backups.</p><p>The UI should explain that browser storage is device-specific and that private browsing, clearing site data, or browser storage eviction can remove local progress. Backups are therefore a required feature, not an optional convenience.</p><h2 id="iphone-and-pwa-requirements" tabindex="-1">iPhone And PWA Requirements <a class="header-anchor" href="#iphone-and-pwa-requirements" aria-label="Permalink to &quot;iPhone And PWA Requirements&quot;">​</a></h2><p>The application will be implemented as a responsive Progressive Web App.</p><h3 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h3><p>On iPhone, the supported installation path is Safari:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Share -&gt; Add to Home Screen</span></span></code></pre></div><p>The hosted application must use HTTPS. GitHub Pages provides the required HTTPS deployment for the public version.</p><h3 id="mobile-interface" tabindex="-1">Mobile Interface <a class="header-anchor" href="#mobile-interface" aria-label="Permalink to &quot;Mobile Interface&quot;">​</a></h3><p>The interface must support:</p><ul><li>Touch-first card flipping</li><li>Large rating buttons</li><li>Comfortable text size</li><li>No hover-only interactions</li><li>Portrait and landscape layouts</li><li>Safe-area padding for iPhone notches and home indicators</li><li>Reduced accidental taps</li><li>Visible progress during a session</li><li>Accessible focus and keyboard behavior where supported</li></ul><h3 id="offline-behavior" tabindex="-1">Offline Behavior <a class="header-anchor" href="#offline-behavior" aria-label="Permalink to &quot;Offline Behavior&quot;">​</a></h3><p>The service worker should cache:</p><ul><li>The application shell</li><li>The generated vocabulary catalog</li><li>Required styles, icons, and assets</li></ul><p>The app should show an offline indicator and continue to support existing cards and local review actions without a network connection.</p><p>When a new catalog is published, the application should update its cached assets without discarding IndexedDB review state. A stale catalog must not prevent review of already cached cards.</p><h3 id="local-development" tabindex="-1">Local Development <a class="header-anchor" href="#local-development" aria-label="Permalink to &quot;Local Development&quot;">​</a></h3><p>Desktop local development will use the existing VitePress development server. iPhone testing should primarily use the hosted HTTPS version. Local-network testing may be added later, but it is not a requirement for the first implementation.</p><h2 id="proposed-project-changes" tabindex="-1">Proposed Project Changes <a class="header-anchor" href="#proposed-project-changes" aria-label="Permalink to &quot;Proposed Project Changes&quot;">​</a></h2><p>The exact filenames may change during implementation, but the expected responsibilities are:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scripts/build-vocabulary-catalog.js</span></span>
<span class="line"><span>docs/flashcards/index.md</span></span>
<span class="line"><span>docs/flashcards/FlashcardApp.vue</span></span>
<span class="line"><span>docs/flashcards/scheduler.js</span></span>
<span class="line"><span>docs/flashcards/reviewStore.js</span></span>
<span class="line"><span>docs/flashcards/flashcards.css</span></span>
<span class="line"><span>docs/flashcards/manifest.webmanifest</span></span>
<span class="line"><span>docs/flashcards/service-worker.js</span></span></code></pre></div><p>The VitePress configuration will add a top-level Flashcards navigation entry and any required route or asset configuration. Generated site output must continue to be produced only through the existing publishing workflow. Generated HTML and assets must not be hand-edited.</p><h2 id="implementation-phases" tabindex="-1">Implementation Phases <a class="header-anchor" href="#implementation-phases" aria-label="Permalink to &quot;Implementation Phases&quot;">​</a></h2><h3 id="phase-1-vocabulary-pipeline" tabindex="-1">Phase 1 -- Vocabulary Pipeline <a class="header-anchor" href="#phase-1-vocabulary-pipeline" aria-label="Permalink to &quot;Phase 1 -- Vocabulary Pipeline&quot;">​</a></h3><ul><li>Implement CSV parsing for all four source files.</li><li>Normalize vocabulary rows.</li><li>Generate card definitions for available fields.</li><li>Add stable card identifiers.</li><li>Add validation for headers and malformed data.</li><li>Handle empty files and missing optional values.</li><li>Verify that adding a CSV row creates cards without application-code changes.</li></ul><h3 id="phase-2-flashcard-vertical-slice" tabindex="-1">Phase 2 -- Flashcard Vertical Slice <a class="header-anchor" href="#phase-2-flashcard-vertical-slice" aria-label="Permalink to &quot;Phase 2 -- Flashcard Vertical Slice&quot;">​</a></h3><ul><li>Add the <code>/flashcards/</code> route.</li><li>Display one generated card.</li><li>Implement flip behavior.</li><li>Display answer details and source metadata.</li><li>Add <code>Again</code>, <code>Hard</code>, <code>Good</code>, and <code>Confident</code> controls.</li><li>Add a basic session queue.</li></ul><p>The phase is complete when a learner can select current vocabulary, flip cards, rate them, and finish a session.</p><h3 id="phase-3-review-persistence-and-scheduling" tabindex="-1">Phase 3 -- Review Persistence And Scheduling <a class="header-anchor" href="#phase-3-review-persistence-and-scheduling" aria-label="Permalink to &quot;Phase 3 -- Review Persistence And Scheduling&quot;">​</a></h3><ul><li>Add IndexedDB storage.</li><li>Add the scheduler adapter.</li><li>Save ratings and due dates.</li><li>Prioritize due and weak cards.</li><li>Add new-card handling.</li><li>Add reload persistence.</li><li>Add export and import.</li><li>Add schema versioning and migration tests.</li></ul><h3 id="phase-4-filters-and-study-modes" tabindex="-1">Phase 4 -- Filters And Study Modes <a class="header-anchor" href="#phase-4-filters-and-study-modes" aria-label="Permalink to &quot;Phase 4 -- Filters And Study Modes&quot;">​</a></h3><ul><li>Add part-of-speech filters.</li><li>Add CEFR, lesson, and topic filters.</li><li>Add <code>de</code> and <code>het</code> filters.</li><li>Add verb tense and subject filters.</li><li>Add direction and card-type filters.</li><li>Add mixed-session balancing.</li><li>Add weak-card and confident-card modes.</li><li>Add session size and progress controls.</li></ul><h3 id="phase-5-responsive-pwa" tabindex="-1">Phase 5 -- Responsive PWA <a class="header-anchor" href="#phase-5-responsive-pwa" aria-label="Permalink to &quot;Phase 5 -- Responsive PWA&quot;">​</a></h3><ul><li>Add responsive mobile styling.</li><li>Add touch-first controls.</li><li>Add safe-area support.</li><li>Add web manifest and app icons.</li><li>Add service worker and offline caching.</li><li>Add offline status and update handling.</li><li>Test Safari Home Screen installation.</li></ul><h3 id="phase-6-verification-and-publishing" tabindex="-1">Phase 6 -- Verification And Publishing <a class="header-anchor" href="#phase-6-verification-and-publishing" aria-label="Permalink to &quot;Phase 6 -- Verification And Publishing&quot;">​</a></h3><ul><li>Test all current vocabulary files, including the empty verbs file.</li><li>Test generated cards for every available part of speech.</li><li>Test new vocabulary ingestion.</li><li>Test stable IDs after source-data edits.</li><li>Test due, weak, new, and confident queues.</li><li>Test filter combinations and mixed sessions.</li><li>Test reload persistence.</li><li>Test export/import.</li><li>Test a production build under <code>/dutch/flashcards/</code>.</li><li>Test desktop and mobile layouts.</li><li>Test offline review on an iPhone.</li><li>Run the existing documentation build and publishing workflow.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><p>The first release is acceptable when:</p><ul><li>The app is reachable at <code>/dutch/flashcards/</code> in the production site.</li><li>New CSV vocabulary appears after rebuilding without editing app code.</li><li>Empty or incomplete vocabulary files do not break the build or app.</li><li>Noun articles can be practiced independently from noun meanings.</li><li>Verb forms can be practiced by tense and subject group.</li><li>Mixed sessions do not overrepresent one vocabulary item because it has many generated cards.</li><li>Ratings change future card ordering.</li><li>Confident cards return for maintenance review.</li><li>Review progress survives closing and reopening the browser.</li><li>Exported progress can be imported successfully.</li><li>The app can be installed on an iPhone from Safari.</li><li>Installed users can review cached cards without a network connection.</li><li>Publishing new vocabulary does not reset existing review progress.</li></ul><h2 id="future-synchronization-option" tabindex="-1">Future Synchronization Option <a class="header-anchor" href="#future-synchronization-option" aria-label="Permalink to &quot;Future Synchronization Option&quot;">​</a></h2><p>The first release intentionally keeps progress local to each device. Desktop and iPhone will therefore have separate review histories.</p><p>If cross-device progress becomes necessary, add synchronization as a separate phase:</p><ul><li>Introduce authentication.</li><li>Store review state in a backend database.</li><li>Retain IndexedDB as an offline cache.</li><li>Define conflict resolution for reviews made on multiple devices.</li><li>Encrypt or minimize personal data where appropriate.</li></ul><p>The local-first storage interface should be designed so this future sync layer can be added without changing the flashcard UI or card-generation pipeline.</p>`,136)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
